<?php
namespace App\Core\Agents\Tools\FirstParty;use App\Core\Agents\Contracts\RiskLevel;use App\Core\Agents\Tools\Contracts\AgentTool;use App\Core\Agents\Tools\DTO\ToolExecutionResult;use App\Models\{AgentRun,Lead};
final class LeadSearchTool implements AgentTool {public function name():string{return 'leads.search';}public function description():string{return 'Search Enverif leads by name, company, email or status.';}public function risk():RiskLevel{return RiskLevel::Read;}public function parameters():array{return ['type'=>'object','properties'=>['query'=>['type'=>'string'],'status'=>['type'=>'string'],'limit'=>['type'=>'integer']]];}public function execute(AgentRun $run,array $a):ToolExecutionResult{$q=Lead::query()->where('workspace_id',$run->workspace_id);if(!empty($a['query'])){$term=(string)$a['query'];$q->where(fn($x)=>$x->where('email','like',"%{$term}%")->orWhere('company','like',"%{$term}%")->orWhere('first_name','like',"%{$term}%")->orWhere('last_name','like',"%{$term}%"));}if(!empty($a['status']))$q->where('status',$a['status']);return ToolExecutionResult::success($q->limit(min(100,max(1,(int)($a['limit']??20))))->get(['id','first_name','last_name','email','title','company','status','score','source','research_summary'])->toArray());}}
